          "warnings": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "What the person is warned of, a sentence each: a file sent although its name is one a secret hides under, and that other entries stay behind unnamed."
          },
          "writes": {
            "type": "object",
            "properties": {
              "path": {
                "type": "string"
              },
              "text": {
                "type": "string"
              }
            },
            "required": [
              "path",
              "text"
            ],
            "additionalProperties": false,
            "description": "The manifest a yes writes into the folder first, if any."
          },
          "sends": {
            "type": "object",
            "properties": {
              "files": {
                "type": "number"
              },
              "bytes": {
                "type": "number"
              }
            },
            "required": [
              "files",
              "bytes"
            ],
            "additionalProperties": false,
            "description": "The whole count and size of what is sent."
          },
          "files": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "path": {
                  "type": "string"
                },
                "bytes": {
                  "type": "number"
                },
                "sha256": {
                  "type": "string"
                },
                "runs": {
                  "type": "boolean",
                  "description": "Whether it is sent as runnable."
                }
              },
              "required": [
                "path",
                "bytes",
                "sha256",
                "runs"
              ],
              "additionalProperties": false
            },
            "description": "The files sent, in the order of their paths."
          },
          "staying": {
            "type": "number",
            "description": "How many entries stay on the machine and are counted here."
          },
          "stays": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "path": {
                  "type": "string"
