                    "link",
                    "hard-link",
                    "ignored",
                    "secret",
                    "never",
                    "generated",
                    "special",
                    "backslash"
                  ]
                },
                "words": {
                  "type": "string"
                }
              },
              "required": [
                "path",
                "why",
                "words"
              ],
              "additionalProperties": false
            },
            "description": "The entries that stay and are named, each with why."
          },
          "list": {
            "type": "object",
            "properties": {
              "sha256": {
                "type": "string"
              },
              "path": {
                "type": "string"
              }
            },
            "required": [
              "sha256"
            ],
            "additionalProperties": false,
            "description": "The list, a line each, of every file sent and every entry that stays and is named, and a last line saying so where entries stay unnamed: its sha256, and the file that holds it."
          },
          "unnamed": {
            "type": "object",
            "properties": {
              "files": {
                "type": "number"
              },
              "stays": {
                "type": "number"
              }
            },
            "required": [
              "files",
              "stays"
            ],
            "additionalProperties": false,
            "description": "Present only when the lists are over the bound: how many files and entries they do not name. The list file names them."
          }
        },
