      const st: StepEvent = {
        type: 'stats',
        ttfbMs,
        totalMs: Math.round(performance.now() - started),
        reqBytes,
        in: u === undefined ? null : u.in + u.cacheRead + u.cacheWrite,
        out: u?.out ?? null,
        ...(u?.reasoning === undefined ? {} : { reasoning: u.reasoning }),
        finish,
