    return found;
  }
  throw missingExecutable(`Executable not found on PATH: ${name}`);
}

function missingExecutable(message: string): NodeJS.ErrnoException {
  const error = new Error(message) as NodeJS.ErrnoException;
  error.code = 'ENOENT';
  return error;
}

const CMD_UNSAFE = /["%!^&|<>\r\n\0]/;

/** True when text can pass through `cmd.exe /d /s /c` as one literal argument. */
export function isCmdSafeArgument(value: string): boolean {
  return !CMD_UNSAFE.test(value);
}

export class UnsafeCommandArgumentError extends Error {
  readonly code = 'EUNSAFEARG';
  readonly argument: string;
  constructor(argument = '') {
    super(
      'Refusing to pass an argument containing cmd.exe metacharacters through a .cmd/.bat launcher; deliver it on stdin instead',
    );
    this.name = 'UnsafeCommandArgumentError';
    this.argument = argument;
  }
}

/**
 * Whether `value` may travel as a command-line argument to this executable on
 * this platform. Only a non-shim `.cmd`/`.bat` launcher restricts arguments.
 */
export function argvSafe(
  executable: string,
  value: string,
  platform = process.platform,
  shimOptions: ExecutableInvocationOptions = {},
): boolean {
  if (platform !== 'win32' || !/\.(?:cmd|bat)$/i.test(executable)) {
    return true;
  }
  return resolveNpmShimTarget(executable, shimOptions) !== undefined || isCmdSafeArgument(value);
}

/** Invoke Windows command shims without shell:true, preserving argument boundaries. */
export function executableInvocation(
  executable: string,
  args: readonly string[],
  platform = process.platform,
  env: NodeJS.ProcessEnv = process.env,
  shimOptions: ExecutableInvocationOptions = {},
): ExecutableInvocation {
  if (platform !== 'win32' || !/\.(?:cmd|bat)$/i.test(executable)) {
    return { command: executable, args: [...args], viaComSpec: false };
  }
  const shimTarget = resolveNpmShimTarget(executable, shimOptions);
  // npm links a package's native binary (Claude Code's bin/claude.exe) through the same
  // shim, so that target runs directly instead of through cmd.exe.
  if (shimTarget && /\.exe$/i.test(shimTarget)) {
    return { command: shimTarget, args: [...args], viaComSpec: false };
  }
  if (shimTarget) {
    return {
      command: process.execPath,
      args: [shimTarget, ...args],
      viaComSpec: false,
    };
  }
  // cmd.exe re-parses the line: it expands %VAR% and does not honor the
  // backslash-quote escape the child's runtime uses. No quoting is provably
  // safe for such text, so refuse it and let callers use stdin or a file.
  for (const value of [executable, ...args]) {
    if (!isCmdSafeArgument(value)) {
      throw new UnsafeCommandArgumentError(value);
    }
  }
  const command = environmentValue(env, 'ComSpec') ?? process.env.ComSpec ?? 'cmd.exe';
  const commandLine = [quoteWindows(executable), ...args.map(quoteWindows)].join(' ');
  return {
    command,
    args: ['/d', '/s', '/c', `"${commandLine}"`],
    viaComSpec: true,
    options: { windowsVerbatimArguments: true },
  };
}

const MAX_SHIM_SIZE = 32 * 1024;
const SHIM_TARGET = /"%dp0%\\([^"\r\n]+\.(?:js|cjs|mjs|exe))"[ \t]+%\*/gi;

function resolveNpmShimTarget(
  executable: string,
  options: ExecutableInvocationOptions,
): string | undefined {
  const readShim = options.readShim ?? ((filename: string) => readFileSync(filename, 'utf8'));
  const exists = options.exists ?? existsSync;
  let contents: string;
  try {
    contents = readShim(executable);
  } catch {
    return undefined;
  }
  if (Buffer.byteLength(contents, 'utf8') > MAX_SHIM_SIZE) {
    return undefined;
  }
  const matches = [...contents.matchAll(SHIM_TARGET)];
  if (matches.length !== 1) {
    return undefined;
  }
  const relativeTarget = matches[0]?.[1];
  if (!relativeTarget || path.win32.isAbsolute(relativeTarget)) {
    return undefined;
  }
  const target = path.win32.resolve(path.win32.dirname(executable), relativeTarget);
  return exists(target) ? target : undefined;
}

function findOnPath(
  pathValue: string,
  candidates: readonly string[],
  exists: (filename: string) => boolean,
  delimiter: string,
  pathModule: typeof path,
): string | undefined {
  for (const directory of pathValue.split(delimiter).filter(Boolean)) {
    for (const candidate of candidates) {
      const filename = pathModule.join(directory, candidate);
      if (exists(filename)) {
        return filename;
      }
    }
  }
  return undefined;
}

function windowsCandidates(name: string, pathext: string | undefined): string[] {
  if (path.extname(name)) {
    return [name];
  }
  const extensions = (pathext ?? '.COM;.EXE;.BAT;.CMD').split(';');
  return [...extensions, ''].map((extension) => `${name}${extension.toLowerCase()}`);
}

function quoteWindows(value: string): string {
  // An unquoted empty argument vanishes from the command line, shifting later values.
  if (value && !/[\s"&()^|<>]/.test(value)) {
    return value;
  }
  return `"${value.replaceAll(/(\\*)"/g, '$1$1\\"').replace(/(\\+)$/, '$1$1')}"`;
}

