    const base: Json = { max_tokens: m.maxOutputTokens }
    if (!m.parallelToolCalls && tools.length > 0) base['tool_choice'] = { type: 'auto', disable_parallel_tool_use: true }
    const { body, level } = params(base, p, m, n.effort)
